// ==== FUNCTION NODE: Process AI Response ====

// Suas referências corretas (já testadas)
const aiResponse = $input.first().json.output;
const webhookData = $('Webhook').first().json.body;
const userContext = webhookData.notes;
const syncType = webhookData.sync_metadata?.type || 'auto_save';
const userStats = webhookData.stats || {};

try {
  // Parse da resposta da IA
  let analysisResult;

  if (aiResponse.choices && aiResponse.choices[0]) {
    // Resposta do OpenAI
    const content = aiResponse.choices[0].message.content;
    analysisResult = JSON.parse(content);
  } else if (aiResponse.content) {
    // Resposta direta
    analysisResult = JSON.parse(aiResponse.content);
  } else if (typeof aiResponse === 'string') {
    // Resposta como string
    analysisResult = JSON.parse(aiResponse);
  } else {
    throw new Error('Formato de resposta inesperado da IA');
  }

  // Validar estrutura básica
  if (!analysisResult.tasks || !Array.isArray(analysisResult.tasks)) {
    throw new Error('Formato de tasks inválido');
  }

  // Preparar contexto do usuário
  const sessionsCompleted = userStats.sessionsCompleted || 0;
  const totalFocusTime = userStats.totalFocusTime || 0;
  const currentMode = userStats.currentMode || 'classic';
  const totalHours = Math.floor(totalFocusTime / 3600);

  // Determinar nível do usuário
  let userLevel = 'iniciante';
  if (sessionsCompleted > 100) userLevel = 'expert';
  else if (sessionsCompleted > 50) userLevel = 'avançado';
  else if (sessionsCompleted > 20) userLevel = 'intermediário';

  // Adicionar insights personalizados
  analysisResult.personal_insights = {
    user_level: userLevel,
    preferred_mode: currentMode,
    productivity_trend: calculateProductivityTrend(sessionsCompleted, totalHours, currentMode),
    recommendations: generatePersonalRecommendations(userLevel, analysisResult, currentMode, sessionsCompleted),
    next_steps: generateNextSteps(analysisResult)
  };

  // Adicionar metadata
  analysisResult.metadata = {
    processed_at: new Date().toISOString(),
    user_id: webhookData.user_id || 'anonymous',
    analysis_type: syncType,
    ai_model: 'openai',
    user_level: userLevel,
    total_tasks: analysisResult.tasks.length,
    processing_time: new Date().getTime()
  };

  // Ajustar formato para análise inline
  if (syncType === 'inline_analysis') {
    analysisResult.tasks = analysisResult.tasks.map(task => ({
      ...task,
      productivity_tips: task.productivity_tips ? task.productivity_tips.slice(0, 1) : ['Mantenha o foco']
    }));
  }

  return [{ json: analysisResult }];

} catch (error) {
  console.error('Erro ao processar resposta da IA:', error);

  // Fallback com análise local
  const fallbackAnalysis = generateFallbackAnalysis(userContext, userStats, syncType);
  return [{ json: fallbackAnalysis }];
}

// ============ FUNÇÕES AUXILIARES ============

function calculateProductivityTrend(sessions, hours, mode) {
  if (sessions === 0) return 'new_user';

  const cycleMinutes = mode === 'classic' ? 25 : mode === 'long' ? 45 : 15;
  const avgSessionLength = (hours * 60) / Math.max(sessions, 1);
  const efficiency = (avgSessionLength / cycleMinutes) * 100;

  if (efficiency > 90) return 'excellent';
  if (efficiency > 75) return 'good';
  if (efficiency > 50) return 'average';
  return 'needs_improvement';
}

function generatePersonalRecommendations(level, analysis, mode, sessions) {
  const recommendations = [];

  if (level === 'iniciante') {
    recommendations.push('Comece com tarefas simples para criar o hábito');
    recommendations.push('Mantenha pausas regulares de 5-15 minutos');
  }

  if (analysis.daily_summary && analysis.daily_summary.total_cycles > 8) {
    recommendations.push('Considere dividir as tarefas em mais dias');
    recommendations.push('Inclua pausas longas para evitar fadiga');
  }

  if (mode === 'classic' && sessions > 30) {
    recommendations.push('Experimente o modo Longo para tarefas complexas');
  }

  if (level === 'expert') {
    recommendations.push('Otimize seus horários de maior energia');
    recommendations.push('Considere técnicas avançadas de time-blocking');
  }

  return recommendations;
}

function generateNextSteps(analysis) {
  const steps = [];

  if (!analysis.tasks || analysis.tasks.length === 0) {
    steps.push('Adicione algumas tarefas às suas notas');
    return steps;
  }

  // Ordenar tarefas por prioridade e complexidade
  const sortedTasks = analysis.tasks.sort((a, b) => {
    const priorityWeight = { high: 3, medium: 2, low: 1 };
    const complexityWeight = { low: 1, medium: 2, high: 3 };

    const scoreA = (priorityWeight[a.priority] || 2) + (complexityWeight[a.complexity] || 2);
    const scoreB = (priorityWeight[b.priority] || 2) + (complexityWeight[b.complexity] || 2);

    return scoreB - scoreA;
  });

  if (sortedTasks[0]) {
    steps.push(`Comece com: ${sortedTasks[0].task.substring(0, 50)}${sortedTasks[0].task.length > 50 ? '...' : ''}`);
  }

  if (analysis.daily_summary && analysis.daily_summary.total_cycles > 6) {
    steps.push('Programe pausas longas a cada 4 ciclos');
  }

  const hardTasks = analysis.tasks.filter(t => t.complexity === 'high');
  if (hardTasks.length > 0) {
    steps.push('Reserve tarefas difíceis para horários de maior energia');
  }

  return steps;
}

function generateFallbackAnalysis(notes, stats, syncType) {
  // Análise local em caso de erro da IA
  const lines = notes.split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 3);

  const tasks = lines.map(line => {
    const task = line.replace(/^[-*•\d.\s]+/, '').trim();
    const keywords = task.toLowerCase();

    // Análise simples de complexidade
    let complexity = 'medium';
    let estimatedTime = 25;

    if (/\b(revisar|verificar|ler|conferir|enviar)\b/i.test(keywords)) {
      complexity = 'low';
      estimatedTime = 15;
    } else if (/\b(criar|desenvolver|implementar|apresentar)\b/i.test(keywords)) {
      complexity = 'high';
      estimatedTime = 45;
    }

    return {
      task: task || 'Tarefa sem nome',
      estimated_time_minutes: estimatedTime,
      pomodoro_cycles: Math.ceil(estimatedTime / 25),
      complexity: complexity,
      priority: 'medium',
      productivity_tips: ['Mantenha o foco durante a execução']
    };
  });

  const totalTime = tasks.reduce((sum, task) => sum + task.estimated_time_minutes, 0);
  const totalCycles = tasks.reduce((sum, task) => sum + task.pomodoro_cycles, 0);

  return {
    tasks: tasks,
    daily_summary: {
      total_estimated_time: totalTime,
      total_cycles: totalCycles,
      suggested_breaks: ['5min após cada ciclo', '15min a cada 2 ciclos'],
      energy_optimization: 'Distribua as tarefas conforme sua energia do dia'
    },
    ai_insights: {
      efficiency_score: 75,
      improvement_areas: ['definir prioridades claras', 'agrupar tarefas similares'],
      personal_patterns: 'Análise local - conecte a IA para insights personalizados',
      workload_assessment: totalCycles <= 4 ? 'light' : totalCycles <= 8 ? 'moderate' : 'heavy'
    },
    personal_insights: {
      user_level: 'iniciante',
      preferred_mode: stats.currentMode || 'classic',
      productivity_trend: 'fallback_analysis',
      recommendations: ['Configure a integração com IA para análises mais precisas'],
      next_steps: ['Teste diferentes modos de Pomodoro', 'Mantenha registro das suas sessões']
    },
    metadata: {
      processed_at: new Date().toISOString(),
      user_id: stats.user_id || 'anonymous',
      analysis_type: 'fallback_local',
      ai_model: 'local_analysis',
      total_tasks: tasks.length,
      processing_time: new Date().getTime()
    }
  };
}
